  'setup.step.workspace_none.w': 'कार्यक्षेत्र में आपकी टीमें, लोग, कार्यक्रम और पैसा रहता है। आप इसके मालिक बनते हैं।',
  'setup.step.legal.t': 'अपना कानूनी नाम और कर संख्या जोड़ें',
  'setup.step.legal.w': 'ये समझौतों और चालानों पर दिखते हैं। अपना GST, VAT या कर संख्या जोड़ें ताकि चालान पहले दिन से मान्य हों।',
  'setup.step.contact.t': 'संपर्क विवरण जोड़ें',
  'setup.step.contact.w': 'एक ईमेल या फ़ोन नंबर जिस पर परिवार और प्रायोजक आपसे संपर्क कर सकें।',
  'setup.step.staff.t': 'अपने कोच और एडमिन को आमंत्रित करें',
  'setup.step.staff.w': 'हर व्यक्ति को भूमिका दें ताकि वे केवल वही देखें जो उन्हें चाहिए।',
  'setup.step.structure.t': 'अपनी पहली टीम बनाएँ',
  'setup.step.structure.w': 'टीमों में आपकी सूची, उपलब्धता और मुकाबले होते हैं।',
  'setup.step.structure_academy.t': 'अपना पहला कार्यक्रम बनाएँ',
  'setup.step.structure_academy.w': 'कार्यक्रमों में आयु सीमा, समय-सारणी और शुल्क होता है जिसके लिए परिवार आवेदन करते हैं।',
  'setup.step.season.t': 'एक सीज़न सेट करें',
  'setup.step.season.w': 'सीज़न आपके कार्यक्रमों, टीमों और उपस्थिति को तारीख देता है।',
  'setup.step.people.t': 'अपने लोगों को लाएँ',
  'setup.step.people.w': 'TeamSnap, SportsEngine या स्प्रेडशीट से अपनी सूची आयात करें। सहेजने से पहले आप सब कुछ देखते हैं।',
  'setup.step.first_transaction.t': 'अपना पहला इवेंट या मुकाबला चलाएँ',
  'setup.step.first_transaction.w': 'ऐसा कुछ बनाएँ जिसे आपके सदस्य देख और जिस पर प्रतिक्रिया दे सकें।',
  'setup.step.first_transaction_academy.t': 'अपना पहला शुल्क लगाएँ',
  'setup.step.first_transaction_academy.w': 'पहला शुल्क या चालान साबित करता है कि आपका पैसे का प्रवाह शुरू से अंत तक काम करता है।',
  'setup.step.venue.t': 'अपना स्थल जोड़ें',
  'setup.step.venue.w': 'नाम, पता और वे खेल जो यहाँ होते हैं।',
  'setup.step.courts.t': 'अपने कोर्ट, मैदान या कमरे जोड़ें',
  'setup.step.courts.w': 'हर एक की अपनी क्षमता और स्लॉट अवधि होती है।',
  'setup.step.hours.t': 'अपने खुलने के समय सेट करें',
  'setup.step.hours.w': 'लोग तभी बुक कर सकते हैं जब आप खुले हों।',
  'setup.step.rates.t': 'अपनी प्रति घंटा दरें सेट करें',
  'setup.step.rates.w': 'कीमतों में कर शामिल है। पीक और ऑफ-पीक नियम बाद में जोड़े जा सकते हैं।',
  'setup.step.first_transaction_venue.t': 'अपनी पहली बुकिंग लें',
  'setup.step.first_transaction_venue.w': 'खुद एक परीक्षण बुकिंग करें, या अपना स्थल पेज साझा करें।',
  'setup.step.event.t': 'अपना इवेंट बनाएँ',
  'setup.step.event.w': 'खेल, तारीखें, स्थल और प्रारूप।',
  'setup.step.open.t': 'इसे प्रविष्टियों के लिए खोलें',
  'setup.step.open.w': 'इवेंट खुलने के बाद ही टीमें प्रवेश कर सकती हैं।',
  'setup.step.first_transaction_organiser.t': 'अपने पहले खेल निर्धारित करें',
  'setup.step.first_transaction_organiser.w': 'समय-सारणी आपके लिए रेफ़री और टीम के टकराव जाँचती है।',
  'setup.step.profile.t': 'अपनी कोच प्रोफ़ाइल सेट करें',
  'setup.step.profile.w': 'आपका शीर्षक, विशेषज्ञता और समय, ताकि लोग आपको ढूँढ और बुक कर सकें।',
  'setup.step.team.t': 'अपनी टीम बनाएँ',
  'setup.step.team.w': 'आपकी सूची, उपलब्धता और समय-सारणी यहीं रहती है।',
  'setup.step.first_transaction_coach.t': 'अपने खिलाड़ियों को आमंत्रित करें',
  'setup.step.first_transaction_coach.w': 'जिन्हें आप जानते हैं उन्हें आमंत्रित करें, या किसी संगठन कार्यक्षेत्र से पूरी सूची लाएँ।',
